UPDATE entidades SET descripcion='Excelente. Enorme playa urbana de 800 metros de longitud situada en el interior de la bahía de Txingudi, en la frontera con Francia. Aguas totalmente mansas y seguras, protegidas por un colosal espigón. Arena fina y dorada. No tiene Bandera Azul' WHERE id=92728;
UPDATE entidades SET descripcion='Excelente. Comparte entorno natural con la playa de Santa Cristina de Lloret, separada de esta por una barrera de rocas naturales. Arena fina y dorada. No tiene Bandera Azul' WHERE id=92807;
