UPDATE entidades SET descripcion='Impresionante vista monumental del cenobio cisterciense del siglo XII a orillas del gran meandro regularizado del Ebro, azudes históricos y huertas. Cómo llegar: Cornisa natural adaptada con balaustrada frente al conjunto monumental, accesible por la carretera A-221. ¡REGISTRO CERRADO Y CONFIRMADO HASTA ESCATRÓN!' WHERE id=125704;
UPDATE entidades SET descripcion='Pequeña estribación caliza exenta que se eleva sobre el fondo plano del valle del Pop. Alberga matorral noble mediterráneo y posee un interés paisajístico estructural comarcal. Alicante) Muro de Alcoy - Puntuación: 64/' WHERE id=128573;
UPDATE entidades SET descripcion='Valle fluvial aluvial maduro donde el río Tormes discurre entre dehesas cuaternarias de gravas y limos finos. Las márgenes mantienen una franja bien conservada de bosque de ribera con chopos negros y sauces que aportan frescura visual en la penillanura. V' WHERE id=132867;
UPDATE entidades SET descripcion='Destacado frente tectónico y erosivo calcarenítico que domina visualmente de forma directa el cauce principal del río Guadalquivir. Las laderas del escarpe albergan formaciones degradadas pero visibles de acebuchal y palmitar rústico, funcionando como un mirador geológico natural. San Nicolás del Puerto - Puntuación: 92' WHERE id=133334;
